insert into public.faqs(id,q,a,published,sort) values ('bd090971-9d4a-4de5-8424-bed79bf978ab','Do you travel for destination weddings?','Yes. We cover weddings across Bengaluru and travel outstation and to destinations — travel and stay are arranged with you as part of the package.',true,0) on conflict do nothing;
insert into public.faqs(id,q,a,published,sort) values ('bb94e0f3-5c2a-4408-b166-460a8cc4c471','What does your coverage include?','We offer candid and traditional photography, cinematic films, pre-wedding shoots, drone coverage and live screening. Packages are customised around your events and budget.',true,1) on conflict do nothing;
insert into public.faqs(id,q,a,published,sort) values ('2e90b489-6261-4a81-919a-b3a2cc079028','Which events do you cover?','Engagements, mehendi, sangeet, haldi, the wedding ceremony, receptions and couple pre-wedding shoots.',true,2) on conflict do nothing;
insert into public.faqs(id,q,a,published,sort) values ('0fa45690-80e3-451b-945d-d9a01ea83653','How early should we book?','Peak wedding dates fill quickly, so we recommend enquiring as soon as your date is fixed. Send your date through the form and we''ll confirm availability.',true,3) on conflict do nothing;
